func:
let origem = "";

if (msg.texto_usuario) {
    origem += msg.texto_usuario + " ";
}

origem += JSON.stringify(msg);

let encontrado = origem.match(/\d{2}\.?\d{3}\.?\d{3}\/?\d{4}-?\d{2}/);

if (!encontrado) {
    node.error("CNPJ não encontrado. Envie um CNPJ com 14 números.", msg);
    return null;
}

let cnpj_limpo = encontrado[0].replace(/[^0-9]/g, "");

msg.url = "https://open.cnpja.com/office/" + cnpj_limpo;
msg.cnpj_cliente = cnpj_limpo;

return msg;

let dados = msg.payload;

function valor(campo, padrao) {
    if (campo === undefined || campo === null || campo === "") {
        return padrao || "Não informado";
    }
    return String(campo);
}

function sql(campo) {
    return valor(campo, "").replace(/'/g, "''");
}

function html(campo) {
    return valor(campo, "")
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;");
}

if (!dados || dados.error || dados.message) {
    let textoErro = "Não consegui consultar esse CNPJ na CNPJá.\n\nVerifique se ele tem 14 números e tente novamente.\n\nExemplo: 00000000000191";

    return [
        {
            payload: {
                chatId: msg.chatId,
                type: "message",
                content: textoErro
            }
        },
        null,
        null
    ];
}

let cnpj = valor(dados.taxId || dados.cnpj || msg.cnpj_cliente);
let razao = valor(dados.company && dados.company.name);
let cidade = valor(dados.address && dados.address.city);
let estado = valor(dados.address && dados.address.state);
let atividade = valor(dados.mainActivity && dados.mainActivity.text);
let situacao = valor(dados.status && dados.status.text);

let situacaoNormalizada = situacao.toUpperCase();

let textoBot = "";

if (situacaoNormalizada !== "ATIVA") {
    textoBot =
        "Encontrei a empresa " + html(razao) + ", mas o CNPJ " + html(cnpj) +
        " está com situação cadastral: " + html(situacao) + ".\n\n" +
        "Deseja consultar outro CNPJ? Responda Sim ou Não.";
} else {
    textoBot =
        "Olá equipe da <b>" + html(razao) + "</b>!\n\n" +
        "Identifiquei o CNPJ " + html(cnpj) + ".\n" +
        "Vi que vocês são de " + html(cidade) + "-" + html(estado) +
        " e atuam com " + html(atividade) + ".\n\n" +
        "Sua cotação B2B personalizada foi liberada com sucesso.\n\n" +
        "Deseja consultar outro CNPJ? Responda Sim ou Não.";
}

let msgTelegram = {
    payload: {
        chatId: msg.chatId,
        type: "message",
        content: textoBot,
        options: {
            parse_mode: "HTML"
        }
    }
};

let msgEmpresa = {
    topic:
        "INSERT OR REPLACE INTO Empresas_B2B " +
        "(CNPJ, Razao_Social, Cidade, Estado, Atividade, Situacao) VALUES (" +
        "'" + sql(cnpj) + "', " +
        "'" + sql(razao) + "', " +
        "'" + sql(cidade) + "', " +
        "'" + sql(estado) + "', " +
        "'" + sql(atividade) + "', " +
        "'" + sql(situacao) + "'" +
        ");"
};

let msgHistorico = {
    topic:
        "INSERT INTO Historico_Chat " +
        "(ChatID, CNPJ, Resposta_Bot) VALUES (" +
        "'" + sql(msg.chatId) + "', " +
        "'" + sql(cnpj) + "', " +
        "'" + sql(textoBot.replace(/<[^>]*>/g, "")) + "'" +
        ");"
};

return [msgTelegram, msgEmpresa, msgHistorico];

let texto = "";

if (typeof msg.payload === "string") {
    texto = msg.payload;
} else {
    texto = msg.payload.content || msg.payload.text || "";
}

let chatId = msg.payload.chatId || msg.chatId;

texto = String(texto).trim();
let textoLower = texto.toLowerCase();

msg.chatId = chatId;
msg.texto_usuario = texto;

let temCnpj = /\d{2}\.?\d{3}\.?\d{3}\/?\d{4}-?\d{2}/.test(texto);

if (
    textoLower === "/start" ||
    textoLower === "start" ||
    textoLower === "olá" ||
    textoLower === "ola" ||
    textoLower === "oi" ||
    textoLower === "/consultar_cnpj" ||
    textoLower === "consultar outro cnpj" ||
    textoLower === "consultar outro" ||
    textoLower === "sim" ||
    textoLower === "/ajuda"
) {
    return [
        {
            payload: {
                chatId: chatId,
                type: "message",
                content: "Olá! Eu consulto dados de empresas pelo CNPJ.\n\nEnvie um CNPJ com 14 números para eu preparar sua cotação B2B personalizada.\n\nExemplo: 00000000000191"
            }
        },
        null
    ];
}

if (
    textoLower === "não" ||
    textoLower === "nao" ||
    textoLower === "sair" ||
    textoLower === "encerrar"
) {
    return [
        {
            payload: {
                chatId: chatId,
                type: "message",
                content: "Atendimento encerrado. Quando quiser consultar outro CNPJ, envie /start."
            }
        },
        null
    ];
}

if (!temCnpj) {
    return [
        {
            payload: {
                chatId: chatId,
                type: "message",
                content: "Não encontrei um CNPJ válido na sua mensagem.\n\nEnvie um CNPJ com 14 números, com ou sem pontuação.\n\nExemplos:\n00000000000191\n00.000.000/0001-91"
            }
        },
        null
    ];
}

msg.payload = texto;

return [null, msg];
